<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$q=trim((string)($_GET['q']??''));$data=catalogProducts($pdo,['q'=>$q,'page'=>$_GET['page']??1,'sort'=>$_GET['sort']??'featured']);$matchedCategories=$matchedBrands=[];
