$pageTitle=($q?'Search: '.$q:'Search').' | Luméa Beauty';$pageDescription=$q?'Search Luméa Beauty for '.$q.'.':'Search cosmetics, skincare, makeup and beauty products at Luméa Beauty.';require __DIR__.'/includes/header.php';?>
<section class="page-title"><span class="eyebrow">LUMÉA BEAUTY</span><h1><?=$q?'Search Results':'Search Luméa Beauty'?></h1><p><?=$q?number_format($data['total']).' products found for “'.e($q).'”.':'Find your next beauty essential.'?></p></section><section class="container" style="padding-bottom:70px">
