<?php if(!$data['items']):?><div class="empty"><i class="bi bi-search"></i><h2>We couldn't find the beauty product you're looking for.</h2><p>Try another product name, brand, category or concern.</p><a class="btn primary" href="<?=url('/shop/')?>">Explore Shop</a></div><?php else:?><div class="catalog-head"><strong><?=number_format($data['total'])?> product matches</strong><form method="get"><input type="hidden" name="q" value="<?=e($q)?>"><select name="sort" onchange="this.form.submit()"><option value="featured">Featured</option><option value="newest" <?=($_GET['sort']??'')==='newest'?'selected':''?>>Latest</option><option value="price_low" <?=($_GET['sort']??'')==='price_low'?'selected':''?>>Price Low to High</option><option value="price_high" <?=($_GET['sort']??'')==='price_high'?'selected':''?>>Price High to Low</option><option value="rating" <?=($_GET['sort']??'')==='rating'?'selected':''?>>Highest Rated</option></select></form></div><div class="product-grid"><?php foreach($data['items'] as $product)require __DIR__.'/includes/product-card.php';?></div><?php if($data['pages']>1):?><nav class="pagination" aria-label="Search pages"><?php for($p=1;$p<=$data['pages'];$p++):?><a class="<?=$p===$data['page']?'active':''?>" href="<?=url('/search.php?'.http_build_query(['q'=>$q,'sort'=>$_GET['sort']??'featured','page'=>$p]))?>"><?=$p?></a><?php endfor;?></nav><?php endif;?><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
